'use strict';
let userAdmin={users:[],branches:[],departments:[]};
const userRoles={admin:['ผู้ดูแลระบบ','จัดการระบบ ผู้ใช้ และข้อมูลทั้งหมด'],kiosk_admin:['ผู้ดูแล Kiosk','จัดการ Kiosk และเปลี่ยน Template'],kiosk_manager:['ผู้ควบคุม Kiosk','เปลี่ยน Template ที่หน้า Kiosk'],counter:['เจ้าหน้าที่เคาน์เตอร์','ดูและดำเนินการคิวตามขอบเขต'],viewer:['ผู้ดูรายงาน','ดูข้อมูลอย่างเดียวตามขอบเขต']};
const userEscape=value=>{const node=document.createElement('span');node.textContent=value??'';return node.innerHTML};
const userDate=value=>{if(!value)return 'ยังไม่เคยเข้าสู่ระบบ';const iso=String(value).replace(' ','T')+(String(value).includes('Z')?'':'Z');return KQThaiDate.dateTime(iso)};
async function renderUsersAdmin(){const [users,branches,departments]=await Promise.all([kqApi('users'),kqApi('branches'),kqApi('departments')]);userAdmin={users:users.data,branches:branches.data,departments:departments.data};document.getElementById('pageTitle').textContent='ผู้ใช้และสิทธิ์';const counts=Object.fromEntries(Object.keys(userRoles).map(role=>[role,userAdmin.users.filter(x=>x.role===role&&Number(x.active)).length]));document.getElementById('viewContent').innerHTML=`<div class="page-card"><div class="page-toolbar"><div><h2>ผู้ใช้และสิทธิ์</h2><p>สร้างบัญชี กำหนดบทบาท และจำกัดขอบเขตการเข้าถึง</p></div><button class="primary" id="addSystemUser">＋ เพิ่มผู้ใช้</button></div><div class="user-role-grid">${Object.entries(userRoles).map(([key,value])=>`<div class="role-summary"><strong>${counts[key]||0}</strong><span>${value[0]}</span></div>`).join('')}</div>${simpleTable(['ผู้ใช้','บทบาท','ขอบเขต','เข้าสู่ระบบล่าสุด','สถานะ',''],userAdmin.users.map(item=>[`<div class="user-name"><strong>${userEscape(item.display_name)}</strong><small>@${userEscape(item.username)}</small></div>`,`<span class="role-pill">${userEscape(userRoles[item.role]?.[0]||item.role)}</span>`,userEscape(item.scope_name||'ทุกสาขาและแผนก'),userDate(item.last_login_at),activeBadge(item.active),`<button class="record-button" data-user-edit="${item.id}">แก้ไข</button>`]),userAdmin.users)}</div>`;document.getElementById('addSystemUser').onclick=()=>openUserDialog();document.querySelectorAll('[data-user-edit]').forEach(button=>button.onclick=()=>openUserDialog(userAdmin.users.find(x=>String(x.id)===button.dataset.userEdit)))}
function scopeOptions(type,selected=''){const list=type==='BRANCH'?userAdmin.branches:type==='DEPARTMENT'?userAdmin.departments:[];return list.map(item=>`<option value="${item.id}" ${String(item.id)===String(selected)?'selected':''}>${userEscape(item.name)}${item.branch_name?` · ${userEscape(item.branch_name)}`:''}</option>`).join('')}
function openUserDialog(record={}){const edit=!!record.id;const wrap=document.createElement('div');wrap.className='crud-backdrop';wrap.innerHTML=`<form class="crud-dialog"><header><div><span class="eyebrow">ACCESS CONTROL</span><h2>${edit?'แก้ไขผู้ใช้':'เพิ่มผู้ใช้'}</h2></div><button type="button" class="icon-button" data-close>×</button></header><div class="crud-form-grid"><input type="hidden" name="id" value="${record.id||0}"><label>ชื่อผู้ใช้<input name="username" value="${userEscape(record.username||'')}" required pattern="[A-Za-z0-9._-]{3,40}" autocomplete="off"></label><label>ชื่อแสดงผล<input name="display_name" value="${userEscape(record.display_name||'')}" required></label><label>บทบาท<select name="role">${Object.entries(userRoles).map(([key,value])=>`<option value="${key}" ${record.role===key?'selected':''}>${value[0]}</option>`).join('')}</select></label><label>ขอบเขต<select name="scope_type"><option value="ALL">ทุกสาขาและแผนก</option><option value="BRANCH" ${record.scope_type==='BRANCH'?'selected':''}>เฉพาะสาขา</option><option value="DEPARTMENT" ${record.scope_type==='DEPARTMENT'?'selected':''}>เฉพาะแผนก</option></select></label><label class="full scope-target">รายการขอบเขต<select name="scope_id"></select></label><label class="full">${edit?'รหัสผ่านใหม่ (เว้นว่างหากไม่เปลี่ยน)':'รหัสผ่านเริ่มต้น'}<input name="password" type="password" minlength="10" ${edit?'':'required'} autocomplete="new-password"></label><div class="scope-help">ผู้ดูแลระบบมีสิทธิ์เต็ม ส่วนบทบาทอื่นจะใช้ขอบเขตนี้ในการเข้าถึงคิวและข้อมูลที่เกี่ยวข้อง</div><label class="toggle-label full"><input name="active" type="checkbox" ${edit?!Number(record.active)?'':'checked':'checked'}> เปิดใช้งานบัญชี</label></div><div class="auth-error hidden" data-error></div><div class="dialog-actions"><button type="button" class="secondary" data-close>ยกเลิก</button><button class="primary">บันทึกผู้ใช้</button></div></form>`;document.body.append(wrap);const form=wrap.querySelector('form'),type=form.scope_type,target=form.scope_id,targetLabel=wrap.querySelector('.scope-target');const updateScope=()=>{targetLabel.classList.toggle('hidden',type.value==='ALL');target.innerHTML=scopeOptions(type.value,record.scope_id)};type.onchange=()=>{record.scope_id='';updateScope()};updateScope();wrap.querySelectorAll('[data-close]').forEach(x=>x.onclick=()=>wrap.remove());form.onsubmit=async event=>{event.preventDefault();const data=Object.fromEntries(new FormData(form));data.active=form.active.checked;try{await kqApi('save-user',{method:'POST',body:JSON.stringify(data)});wrap.remove();showToast('บันทึกผู้ใช้และสิทธิ์เรียบร้อย');await renderUsersAdmin()}catch(error){const box=wrap.querySelector('[data-error]');box.textContent=error.message;box.classList.remove('hidden')}}}
document.querySelectorAll('.nav-item[data-view="users"]').forEach(node=>node.onclick=()=>{document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n===node));document.getElementById('dashboardView').classList.add('hidden');document.getElementById('genericView').classList.remove('hidden');document.getElementById('sidebar').classList.remove('open');renderUsersAdmin().catch(error=>showToast(error.message))});
